// File storage on DigitalOcean Spaces. The only code that talks to Spaces;
// the rest of the app stores and reads files through the functions below.
//
// Files are uploaded public-read and served from the Spaces CDN
// (DO_SPACES_CDN_URL), under DO_SPACES_FOLDER in DO_SPACES_BUCKET:
//   <folder>/assets/<sha256>.<ext>                 website images
//   <folder>/passes/<passId>-v<version>-<token>.png entry pass images
//   <folder>/photos/<token>.jpg                     registrants' photos
// Every name is generated by the server and never changes content, so the
// CDN may cache them for a year. Pass and photo names carry a random token,
// so their URLs cannot be guessed.
const crypto = require('crypto');
const {
  S3Client,
  PutObjectCommand,
  GetObjectCommand,
  DeleteObjectCommand,
  HeadObjectCommand,
  ListObjectsV2Command,
} = require('@aws-sdk/client-s3');
const { env } = require('../config/env');

const KEY_RE = /^[a-f0-9]{64}\.(jpg|png)$/;
const PASS_KEY_RE = /^[2-9A-HJKMNP-Z]{4}-[2-9A-HJKMNP-Z]{4}-[2-9A-HJKMNP-Z]{4}-v\d+-[a-f0-9]{32}\.png$/;
const PHOTO_KEY_RE = /^[a-f0-9]{32}\.jpg$/;
const IMMUTABLE = 'public, max-age=31536000, immutable';

let client;
function s3() {
  if (!client) {
    client = new S3Client({
      endpoint: env.spaces.endpoint,
      region: env.spaces.region,
      credentials: { accessKeyId: env.spaces.key, secretAccessKey: env.spaces.secret },
    });
  }
  return client;
}

const objectKey = (dir, name) => [env.spaces.folder, dir, name].filter(Boolean).join('/');

function cdnUrl(dir, name) {
  return `${env.spaces.cdnUrl}/${objectKey(dir, name).split('/').map(encodeURIComponent).join('/')}`;
}

const notFound = (err) => err?.name === 'NoSuchKey' || err?.name === 'NotFound' || err?.$metadata?.httpStatusCode === 404;

async function exists(dir, name) {
  try {
    await s3().send(new HeadObjectCommand({ Bucket: env.spaces.bucket, Key: objectKey(dir, name) }));
    return true;
  } catch (err) {
    if (notFound(err)) return false;
    throw err;
  }
}

async function put(dir, name, buffer, mime) {
  await s3().send(
    new PutObjectCommand({
      Bucket: env.spaces.bucket,
      Key: objectKey(dir, name),
      Body: buffer,
      ContentType: mime,
      CacheControl: IMMUTABLE,
      ACL: 'public-read',
    })
  );
}

async function get(dir, name) {
  try {
    const res = await s3().send(new GetObjectCommand({ Bucket: env.spaces.bucket, Key: objectKey(dir, name) }));
    return Buffer.from(await res.Body.transformToByteArray());
  } catch (err) {
    if (notFound(err)) return null;
    throw err;
  }
}

async function remove(dir, name) {
  await s3().send(new DeleteObjectCommand({ Bucket: env.spaces.bucket, Key: objectKey(dir, name) }));
}

/** [{ name, modified }] of the files in a folder. */
async function list(dir) {
  const prefix = `${objectKey(dir, '')}/`;
  const files = [];
  let token;
  do {
    const res = await s3().send(new ListObjectsV2Command({ Bucket: env.spaces.bucket, Prefix: prefix, ContinuationToken: token }));
    for (const o of res.Contents || []) files.push({ name: o.Key.slice(prefix.length), modified: o.LastModified ? new Date(o.LastModified) : null });
    token = res.IsTruncated ? res.NextContinuationToken : undefined;
  } while (token);
  return files;
}

function checkKey(key) {
  // Keys are generated by the server; this also rules out path traversal.
  if (!KEY_RE.test(key)) throw new Error(`Invalid asset key: ${key}`);
}

function checkPassKey(key) {
  if (!PASS_KEY_RE.test(key)) throw new Error(`Invalid pass image key: ${key}`);
}

function checkPhotoKey(key) {
  if (!PHOTO_KEY_RE.test(key)) throw new Error(`Invalid photo key: ${key}`);
}

// Website images, named by content hash ("<sha256>.jpg").
const assets = {
  async put(key, buffer, mime) {
    checkKey(key);
    if (await exists('assets', key)) return; // content-addressed: same key, same bytes
    await put('assets', key, buffer, mime);
  },
  get: (key) => (checkKey(key), get('assets', key)),
  remove: (key) => (checkKey(key), remove('assets', key)),
  list: async () => (await list('assets')).map((f) => f.name).filter((k) => KEY_RE.test(k)),
  url: (key) => (checkKey(key), cdnUrl('assets', key)),
  KEY_RE,
};

// Entry pass images.
const passes = {
  newKey: (passId, version) => `${passId}-v${version}-${crypto.randomBytes(16).toString('hex')}.png`,
  put: (key, buffer) => (checkPassKey(key), put('passes', key, buffer, 'image/png')),
  get: (key) => (checkPassKey(key), get('passes', key)),
  url: (key) => (checkPassKey(key), cdnUrl('passes', key)),
};

// Registrants' photos, uploaded before the form is submitted.
const photos = {
  newKey: () => `${crypto.randomBytes(16).toString('hex')}.jpg`,
  put: (key, buffer) => (checkPhotoKey(key), put('photos', key, buffer, 'image/jpeg')),
  get: (key) => (checkPhotoKey(key), get('photos', key)),
  exists: (key) => (checkPhotoKey(key), exists('photos', key)),
  remove: (key) => (checkPhotoKey(key), remove('photos', key)),
  url: (key) => (checkPhotoKey(key), cdnUrl('photos', key)),
  list: async () => (await list('photos')).filter((f) => PHOTO_KEY_RE.test(f.name)),
  KEY_RE: PHOTO_KEY_RE,
};

/** Origin of the CDN, for the Content Security Policy. */
const cdnOrigin = () => new URL(env.spaces.cdnUrl).origin;

module.exports = { ...assets, passes, photos, cdnOrigin };
